from typing import Optional, List


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    # Check if the first characters of rows and columns are compatible
    for i in range(n):
        for j in range(n):
            if r[i] == c[j]:
                # This cell must contain r[i]/c[j]
                pass
            else:
                # This cell cannot contain both r[i] and c[j] if they're different
                pass

    # Since n is small (3-5), we can use backtracking
    grid = [['.' for _ in range(n)] for _ in range(n)]

    # First, place the mandatory characters
    for i in range(n):
        grid[i][0] = r[i]
    for j in range(n):
        grid[0][j] = c[j]

    # Check for conflicts in the top-left corner
    if grid[0][0] != r[0] or grid[0][0] != c[0]:
        return None

    # We'll use backtracking to fill the rest
    # We need to track which characters are used in each row and column
    row_chars = [{'A': False, 'B': False, 'C': False} for _ in range(n)]
    col_chars = [{'A': False, 'B': False, 'C': False} for _ in range(n)]

    # Initialize the tracking
    for i in range(n):
        row_chars[i][r[i]] = True
    for j in range(n):
        col_chars[j][c[j]] = True

    # Now fill the grid
    def backtrack(pos):
        if pos == n * n:
            return True

        i, j = pos // n, pos % n

        # Skip if already filled
        if grid[i][j] != '.':
            return backtrack(pos + 1)

        # Try all possible characters
        for char in ['A', 'B', 'C']:
            # Skip if already used in this row or column
            if row_chars[i][char] or col_chars[j][char]:
                continue

            # Check if placing this character would violate constraints
            # For the first column, we must have r[i]
            if j == 0 and char != r[i]:
                continue
            # For the first row, we must have c[j]
            if i == 0 and char != c[j]:
                continue

            # Place the character
            grid[i][j] = char
            row_chars[i][char] = True
            col_chars[j][char] = True

            # Recurse
            if backtrack(pos + 1):
                return True

            # Backtrack
            grid[i][j] = '.'
            row_chars[i][char] = False
            col_chars[j][char] = False

        return False

    # Start backtracking from position 1 (since position 0 is already filled)
    if backtrack(1):
        return [''.join(row) for row in grid]
    else:
        return None
